<script lang="ts">
 import {onMount} from 'svelte';
 let password='';let loggedIn=false;let message='';let siteSettings='';let settingsRevision:string|null=null;let kind:'posts'|'dynamic'='posts';let id='';let title='';let body='';let state='draft';let fields='{}';let expectedRev:string|null=null;let history:any[]=[];let list:any[]=[];let working=false;let galleryText='';let galleryRevision:string|null=null;let galleryLoaded=false;let backupUrl='/api/firefly/backup';let uploadFolder='photos/castorice';let selectedUpload:File|null=null;let imagebedFiles:any[]=[];let imagebedMessage='';let imagebedWorking=false;let previewDoc='';let previewLoading=false;let previewError='';let previewTimer:ReturnType<typeof setTimeout>|null=null;let previewSeq=0;
 const root='/api/firefly';
 onMount(async()=>{try{const r=await api('/session');loggedIn=!!r.authenticated;if(loggedIn)await refresh()}catch{loggedIn=false}});
 async function api(path:string,init?:RequestInit){const r=await fetch(root+path,{credentials:'same-origin',...init});let data=await r.json().catch(()=>({error:'Invalid JSON'}));if(!r.ok)throw new Error(data.error||`HTTP ${r.status}`);return data;}
 async function login(){message='';try{await api('/session',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({password})});password='';loggedIn=true;await refresh()}catch(e){message=String(e)}}
 async function refresh(){try{const d=await api(`/content?kind=${kind}`);list=d.items||[];message=''}catch(e){message=String(e)}}
 function edit(item:any){previewDoc='';previewError='';id=item.id;title=item.title||'';body=item.body||'';state=item.state||'draft';fields=JSON.stringify(item.fields||{},null,2);expectedRev=item.rev||null;history=[];}
 function createNew(){previewDoc='';previewError='';id='';title='';body='';state='draft';fields='{}';expectedRev=null;history=[];}
 async function fetchPreview(){
   const seq=++previewSeq;previewLoading=true;previewError='';
   try{const data=await api('/preview',{method:'POST',headers:{'Content-Type':'application/json','X-Firefly-CMS':'1'},body:JSON.stringify({title,body})});
   if(seq===previewSeq)previewDoc=data.html||'';
   }catch(e){if(seq===previewSeq)previewError=String(e)}finally{if(seq===previewSeq)previewLoading=false}
 }
 function queuePreview(){if(previewTimer)clearTimeout(previewTimer);previewTimer=setTimeout(()=>{if(loggedIn)fetchPreview()},380)}
 async function save(){working=true;message='';try{if(!/^[a-zA-Z0-9][a-zA-Z0-9_-]{0,119}$/.test(id))throw new Error('ID 须为字母、数字、_、-，且不能空白');const item={title,body,state,fields:JSON.parse(fields)};const r=await api(`/content?kind=${kind}&id=${encodeURIComponent(id)}`,{method:'POST',headers:{'Content-Type':'application/json','X-Firefly-CMS':'1'},body:JSON.stringify({action:expectedRev?'update':'create',expectedRev,item})});edit(r.item);const verified=await api(`/content?kind=${kind}&id=${encodeURIComponent(id)}`);if(verified.rev!==r.item.rev)throw new Error('保存完成但读取确认失败，请先刷新检查');message='已写入并通过读取确认，请检查前台是否同步更新';await refresh()}catch(e){message=String(e)}finally{working=false}}
 async function remove(){if(!expectedRev||!confirm('确定要删除？可从修订历史恢复。'))return;working=true;try{const r=await api(`/content?kind=${kind}&id=${encodeURIComponent(id)}`,{method:'POST',headers:{'Content-Type':'application/json','X-Firefly-CMS':'1'},body:JSON.stringify({action:'delete',expectedRev})});edit(r.item);message='已标记删除';await refresh()}catch(e){message=String(e)}finally{working=false}}
 async function getHistory(){try{const r=await api(`/content?kind=${kind}&id=${encodeURIComponent(id)}&action=history`);history=r.history||[]}catch(e){message=String(e)}}
 async function restore(rev:string){working=true;try{const r=await api(`/content?kind=${kind}&id=${encodeURIComponent(id)}`,{method:'POST',headers:{'Content-Type':'application/json','X-Firefly-CMS':'1'},body:JSON.stringify({action:'restore',expectedRev,fromRev:rev})});edit(r.item);message='修订已恢复';await refresh()}catch(e){message=String(e)}finally{working=false}}
 async function loadSettings(){try{const s=await api('/settings');settingsRevision=s.revision||null;siteSettings=JSON.stringify(s,null,2)}catch(e){message=String(e)}}
 async function saveSettings(){try{const settings=JSON.parse(siteSettings);const x=await api('/settings',{method:'PUT',headers:{'Content-Type':'application/json','X-Firefly-CMS':'1'},body:JSON.stringify({settings,expectedRevision:settingsRevision})});settingsRevision=x.revision;siteSettings=JSON.stringify(x,null,2);message='设置已保存，具体页面是否实时生效还需要前台验证'}catch(e){message=String(e)}}
 async function loadGallery(){try{const m=await api('/gallery');galleryRevision=m.revision||null;galleryText=JSON.stringify(m,null,2);galleryLoaded=true;message=''}catch(e){message=String(e)}}
 async function saveGallery(){working=true;try{const manifest=JSON.parse(galleryText);const r=await api('/gallery',{method:'PUT',headers:{'Content-Type':'application/json','X-Firefly-CMS':'1'},body:JSON.stringify({manifest,expectedRevision:galleryRevision})});galleryRevision=r.manifest.revision;galleryText=JSON.stringify(r.manifest,null,2);message='图库目录保存成功；没有修改原始图片'}catch(e){message=String(e)}finally{working=false}}
 async function listImagebed(){imagebedWorking=true;imagebedMessage='';try{const r=await api(`/imagebed?action=list&dir=${encodeURIComponent(uploadFolder)}&recursive=false`);imagebedFiles=r.files||[];imagebedMessage=`读取 ${imagebedFiles.length} 个图床文件`}catch(e){imagebedMessage=String(e)}finally{imagebedWorking=false}}
 async function uploadImagebed(){if(!selectedUpload)return;imagebedWorking=true;imagebedMessage='';try{const form=new FormData();form.append('file',selectedUpload);const r=await fetch(`${root}/imagebed?action=upload&folder=${encodeURIComponent(uploadFolder)}`,{method:'POST',credentials:'same-origin',headers:{'X-Firefly-CMS':'1'},body:form});const j=await r.json();if(!r.ok)throw Error(j.error||'上传失败');selectedUpload=null;imagebedMessage='图片上传完成；请刷新相册清单并更新图片排序';await listImagebed()}catch(e){imagebedMessage=String(e)}finally{imagebedWorking=false}}
 async function deleteImagebed(key:string){if(!confirm('确定从图床永久删除该图片？此操作不可撤销。'))return;imagebedWorking=true;try{await api('/imagebed?action=delete',{method:'POST',headers:{'Content-Type':'application/json','X-Firefly-CMS':'1'},body:JSON.stringify({key})});imagebedMessage='图片已从图床删除';await listImagebed()}catch(e){imagebedMessage=String(e)}finally{imagebedWorking=false}}
 async function renameImagebed(key:string){const newKey=prompt('请输入新完整路径（photos/相册/文件名）',key);if(!newKey||newKey===key)return;imagebedWorking=true;try{await api('/imagebed?action=rename',{method:'POST',headers:{'Content-Type':'application/json','X-Firefly-CMS':'1'},body:JSON.stringify({key,newKey})});imagebedMessage='图片重命名完成；如已被相册引用，请更新相册目录';await listImagebed()}catch(e){imagebedMessage=String(e)}finally{imagebedWorking=false}}
 async function logout(){try{await api('/session',{method:'DELETE'})}catch{}loggedIn=false;password='';message=''}
</script>
{#if !loggedIn}<p class="muted">登录需要部署环境中的独立管理员密码。密码不会写入 GitHub、静态页面或浏览器长期存储。</p>
<form onsubmit={e=>{e.preventDefault();login()}}><input class="input" type="password" bind:value={password} placeholder="管理员密码" autocomplete="current-password"/><p><button class="btn" type="submit">登录</button></p></form>
{:else}<div class="actions"><button class="icon-btn" onclick={()=>{kind='posts';refresh()}}>文章</button><button class="icon-btn" onclick={()=>{kind='dynamic';refresh()}}>动态</button><button class="icon-btn" onclick={createNew}>新建</button><button class="icon-btn" onclick={logout}>退出</button></div>
<p><a href="/api/firefly/backup" target="_blank" rel="noopener noreferrer">下载内容/相册/设置备份 JSON</a></p><details><summary onclick={loadSettings}>站点设置</summary><p class="muted">已单独持久化；改动不会写入 GitHub。</p><textarea class="input" bind:value={siteSettings} rows="10" placeholder="加载站点设置"></textarea><button class="btn" onclick={saveSettings}>保存设置</button></details><details><summary onclick={loadGallery}>相册管理 · 目录与封面排序</summary><p class="muted">编辑相册名称、封面、描述、标签及 photoOrder 列表。这里不会删除、重命名或上传图床上的原图。受保护相册的秘密字段只会在已登录状态读取。</p>
 {#if galleryLoaded}<label>Gallery manifest JSON<textarea class="input" bind:value={galleryText} rows="13"></textarea></label><button class="btn" type="button" disabled={working} onclick={saveGallery}>保存相册目录</button>{/if}</details>
 <details><summary>图床管理 · 图片上传 / 重命名 / 删除</summary>
 <p class="muted">直接管理现有 Cloudflare 图片床；需要在 EdgeOne 中设置 FIREFLY_IMAGEBED_TOKEN。删除不可撤销，不会自动修改相册引用。</p>
 <label>图床相册目录<input class="input" bind:value={uploadFolder} placeholder="photos/castorice" /></label>
 <div class="actions"><button class="icon-btn" type="button" disabled={imagebedWorking} onclick={listImagebed}>列出图片</button><input type="file" accept="image/png,image/jpeg,image/webp,image/avif,image/gif" onchange={(e)=>{selectedUpload=e.currentTarget.files?.[0]||null}}/><button class="icon-btn" type="button" disabled={!selectedUpload||imagebedWorking} onclick={uploadImagebed}>上传图片</button></div>
 {#if imagebedMessage}<p class="note">{imagebedMessage}</p>{/if}
 {#each imagebedFiles as f}<div class="list-link"><span>{f.name||f.key} · {f.metadata?.FileSizeBytes||0} B</span><button class="icon-btn" type="button" disabled={imagebedWorking} onclick={()=>renameImagebed(f.name||f.key)}>重命名</button><button class="icon-btn" type="button" disabled={imagebedWorking} onclick={()=>deleteImagebed(f.name||f.key)}>永久删除</button></div>{/each}
 </details>
 <div class="grid-cards" style="margin-top:18px"><div><h3>已有内容</h3>{#each list as x}<button type="button" class="list-link" onclick={()=>edit(x)}>{x.title||x.id} ({x.state})</button>{/each}</div><form onsubmit={e=>{e.preventDefault();save()}}><label>内容 ID<input class="input" bind:value={id} /></label><label>标题<input class="input" bind:value={title} oninput={queuePreview}/></label><label>发布状态<select class="input" bind:value={state}><option value="draft">草稿</option><option value="published">公开</option><option value="private">私密</option><option value="deleted">删除</option></select></label><label>Markdown 正文<textarea class="input" rows="12" bind:value={body} oninput={queuePreview}></textarea></label><label>Frontmatter / 自定义字段<textarea class="input" rows="6" bind:value={fields}></textarea></label><div class="actions"><button class="icon-btn" type="button" onclick={fetchPreview} disabled={previewLoading}>立即预览</button></div>
 <section class="card-base p-3" aria-label="实时草稿预览"><h3>草稿实时预览 <small class="muted">不发布、不写入数据库</small></h3>
 {#if previewLoading}<p>正在刷新预览…</p>{/if}{#if previewError}<p class="note" role="alert">{previewError}</p>{/if}
 {#if previewDoc}<iframe title="草稿实时预览" sandbox="" srcdoc={previewDoc} style="width:100%;height:430px;border:1px solid var(--line-divider);border-radius:8px" />{:else}<p class="muted">在右侧输入内容后会自动生成受保护的预览。</p>{/if}
 </section>
 <div class="actions"><button class="btn" disabled={working}>保存</button><button class="icon-btn" type="button" disabled={working||!expectedRev} onclick={getHistory}>修订历史</button><button class="icon-btn" type="button" disabled={working||!expectedRev} onclick={remove}>删除</button></div></form></div>
{#if history.length}<h3>修订历史</h3>{#each history as h}<div class="list-link">{h.updatedAt} {h.state} <button class="icon-btn" disabled={working} onclick={()=>restore(h.rev)}>恢复此版本</button></div>{/each}{/if}
{/if}
{#if message}<p class="note" role="status">{message}</p>{/if}
